from cyclopts import run


def greet(name: str, excited: bool = False):
    """Print a greeting to the given name."""
    greeting = f"Hello, {name}"
    if excited:
        greeting += "!"
    else:
        greeting += "."
    print(greeting)


if __name__ == "__main__":
    run(greet)
